// Find a sibling Project – file in the same folder as filePath
const filePath      = $json.filePath ?? '';
const allKnownFiles = Array.isArray($json.allKnownFiles) ? $json.allKnownFiles : [];

const parts  = filePath.split('/');
const folder = parts.length > 1 ? parts.slice(0, -1).join('/') : null;

let siblingPath = null;

if (folder) {
  // Only assign if exactly one Project – file exists in the folder
  // Multiple siblings = ambiguous = treat as no sibling
  const siblings = allKnownFiles.filter(f => {
    const fParts  = f.split('/');
    const fFolder = fParts.length > 1 ? fParts.slice(0, -1).join('/') : null;
    const fName   = fParts[fParts.length - 1];
    return fFolder === folder && /^Project\s*[\u2013\-]/i.test(fName);
  });
  if (siblings.length === 1) siblingPath = siblings[0];
}

return {
  ...$json,
  siblingPath,
};

// Parse project and area from the sibling Project – file frontmatter
// If the HTTP fetch failed or returned no content, return empty strings.

const siblingPath = $('Find Sibling Path').item.json.siblingPath ?? '';
const content = $json.data ?? $json.body ?? '';

let siblingProjectSlug = '';
let siblingProjectArea = '';

if (content) {
  const fmMatch = content.match(/^---\s*[\r\n]+([\s\S]*?)[\r\n]+---\s*[\r\n]+/);
  if (fmMatch) {
    for (const line of fmMatch[1].split('\n')) {
      const colon = line.indexOf(':');
      if (colon === -1) continue;
      const key   = line.slice(0, colon).trim();
      const value = line.slice(colon + 1).trim();
      if (key === 'project' && value) siblingProjectSlug = value;
      if (key === 'area'    && value) siblingProjectArea = value;
    }
  }

  // If project slug absent from frontmatter, slugify the sibling filename
  if (!siblingProjectSlug && siblingPath) {
    const siblingFilename = siblingPath.split('/').pop().replace(/\.md$/, '');
    siblingProjectSlug = siblingFilename
      .replace(/^(?:Project|Research|Wiki|Log|Meta|Area)\s*[\u2013\-]\s*/i, '')
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
  }
}

return {
  siblingPath,
  siblingProjectSlug,
  siblingProjectArea,
};
